use xiom.io;
fn is_palindrome(s: Str) -> Bool {
  if s.len() == 0 { return true; };
  var left = 0;
  var right = s.len() - 1;
  while left < right {
    let lc = s.char_at(left);
    let rc = s.char_at(right);
    if lc != rc { return false; };
    left += 1;
    right -= 1;
  };
  true
}

fn main() -> Int {
  io.println(is_palindrome("racecar").to_str());
  io.println(is_palindrome("hello").to_str());
  io.println(is_palindrome("abba").to_str());
  return 0;
}
